-- =============================================================================
-- Portfolio sync: brings portfolio_items in line with src/content/site.ts.
--
-- Matches an existing row by link first, then by title. Matched rows are
-- updated (description, image, video, category). Unmatched site entries are
-- inserted. Rows in the database that are not in the site file are kept and
-- pushed to the end of the list; nothing is deleted.
--
-- Safe to run more than once.
-- =============================================================================

begin;

create temporary table portfolio_src (
  pos         int,
  title       text,
  category    text,
  description text,
  image_url   text,
  video_url   text,
  link        text
) on commit drop;


-- 1. Update rows that already exist.
update portfolio_items p
set title       = s.title,
    category    = s.category,
    description = s.description,
    image_url   = s.image_url,
    video_url   = s.video_url,
    link        = s.link,
    sort_order  = s.pos
from portfolio_src s
where (p.link is not null and s.link is not null and p.link = s.link)
   or (lower(p.title) = lower(s.title));

-- 2. Insert the ones that are missing.
select s.title, s.category, s.description, s.image_url, s.video_url, s.link, false, s.pos
from portfolio_src s
where not exists (
  select 1 from portfolio_items p
  where (p.link is not null and s.link is not null and p.link = s.link)
     or (lower(p.title) = lower(s.title))
);

-- 3. Anything in the database but not in the site file keeps its row and goes last.
update portfolio_items p
set sort_order = 54 + p.sort_order
where not exists (
  select 1 from portfolio_src s
  where (p.link is not null and s.link is not null and p.link = s.link)
     or (lower(p.title) = lower(s.title))
);

commit;

-- Check: should list the site order first, then any extras.
select sort_order, title, category, (video_url is not null) as has_video
from portfolio_items order by sort_order;
